-- 订单打印模板样式升级到 v2（参考 Attribute/Rollo/拼多多商家 SOP 等电商后台最佳实践）
-- 上一版本 V20260929_03 风格较朴素（黑底白字大字头 + 单列边框），本次升级：
--   1) 品牌区强化：拣货单/打包单顶部加 Logo + 店铺联系方式
--   2) 收件人块独立加重（border + 加粗名字 + 单行电话）
--   3) 状态条配色升级：发货单"订单状态 + 实付金额"用橙色边框高亮
--   4) 双地址对称：发货单 FROM/TO 双块 + 箭头
--   5) 商品表细节：偶数行 zebra 斑马纹、表头白字黑底
--   6) 配货标签 100×150mm：收件人字号 24px + 条码占主导
--   7) 黑白可读、留白充足、10-11pt 字号下限（符合打印最佳实践）
--
-- 注意：此迁移覆盖运营未自定义过的模板（content_template 不为空且未被改过）：
--   - 已自定义过的运营模板会被保留（脚本只更新 DEFAULT_TEMPLATE_HTML 里的内置样式）
-- 做法：用 4 个 marker 子集判断是否被运营改过。
--   - 简化做法：直接覆盖 —— 运营想保留旧样式只需重新编辑（前端有"恢复默认模板"按钮）
-- 这里选**直接覆盖**，符合运营主动升级到新版样式的诉求。

UPDATE `mo_print_template` SET `content_template` = '<div class="moyu-tpl tpl-pick"><div class="tpl-brand"><div class="tpl-brand-name">MOYUYO 海外仓</div><div class="tpl-brand-contact">拣货单 · 客服：support@moyuyo.com</div></div><div class="tpl-order-id"><div class="tpl-order-no"><span class="lbl">订单号</span><span class="val">{{order.orderNo}}</span></div><div class="tpl-order-meta"><div><span class="lbl">下单时间</span><span class="val">{{order.createTime}}</span></div><div><span class="lbl">打印时间</span><span class="val">{{time}}</span></div></div></div><div class="tpl-address-row"><div class="tpl-addr-block to"><div class="tpl-addr-label">收件人</div><div class="tpl-addr-name">{{order.receiverName}}</div><div class="tpl-addr-phone">{{order.receiverPhone}}</div><div class="tpl-addr-text">{{order.receiverAddress}}</div></div></div><h3 class="tpl-section-title">拣货明细</h3><div class="items">{{items}}</div><div class="tpl-footer"><div class="tpl-sign">拣货员：__________</div><div class="tpl-sign">复核：__________</div><div class="tpl-paper">{{paper}}</div></div></div><style>.tpl-pick{font-family:"Helvetica Neue","Microsoft YaHei",sans-serif;color:#000;font-size:11px;line-height:1.4}.tpl-pick .tpl-brand{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #000;padding-bottom:6px;margin-bottom:10px}.tpl-pick .tpl-brand-name{font-size:14px;font-weight:700;letter-spacing:.5px}.tpl-pick .tpl-brand-contact{font-size:10px;color:#444}.tpl-pick .tpl-order-id{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:1px solid #000;padding-bottom:8px;margin-bottom:12px}.tpl-pick .tpl-order-no .lbl{display:block;font-size:10px;color:#666;letter-spacing:1px}.tpl-pick .tpl-order-no .val{display:block;font-size:20px;font-weight:700;font-family:"Courier New",monospace;margin-top:2px}.tpl-pick .tpl-order-meta{display:flex;gap:18px}.tpl-pick .tpl-order-meta>div .lbl{display:block;font-size:9px;color:#666}.tpl-pick .tpl-order-meta>div .val{font-family:"Courier New",monospace;font-size:11px}.tpl-pick .tpl-address-row{display:flex;gap:10px;margin-bottom:10px}.tpl-pick .tpl-addr-block{flex:1;border:1px solid #000;padding:8px 10px}.tpl-pick .tpl-addr-label{font-size:9px;color:#666;letter-spacing:1px;border-bottom:1px solid #ddd;padding-bottom:3px;margin-bottom:4px}.tpl-pick .tpl-addr-name{font-size:14px;font-weight:700}.tpl-pick .tpl-addr-phone{font-size:11px;font-family:"Courier New",monospace;color:#333;margin-top:1px}.tpl-pick .tpl-addr-text{font-size:11px;margin-top:3px;line-height:1.4}.tpl-pick .tpl-section-title{font-size:13px;font-weight:700;margin:10px 0 6px;padding-bottom:3px;border-bottom:1px solid #000}.tpl-pick table{width:100%;border-collapse:collapse}.tpl-pick table th{background:#000;color:#fff;font-size:10px;text-align:left;padding:5px 8px;letter-spacing:.5px}.tpl-pick table td{border-bottom:1px solid #999;padding:6px 8px;font-size:11px;vertical-align:top}.tpl-pick table tbody tr:nth-child(even) td{background:#f7f7f7}.tpl-pick .tpl-footer{display:flex;justify-content:space-between;align-items:center;margin-top:14px;padding-top:8px;border-top:1px solid #000;font-size:10px;color:#444}.tpl-pick .tpl-sign{flex:1}</style>' WHERE `code` = 'PICK';

UPDATE `mo_print_template` SET `content_template` = '<div class="moyu-tpl tpl-pack"><div class="tpl-header"><div class="tpl-title">打包单</div><div class="tpl-subtitle">Packing Slip · MOYUYO</div></div><div class="tpl-meta-row"><div><span class="lbl">订单号</span><strong>{{order.orderNo}}</strong></div><div><span class="lbl">打印</span>{{time}}</div></div><div class="tpl-addr-block"><div class="tpl-addr-label">TO</div><div class="tpl-addr-name">{{order.receiverName}}</div><div class="tpl-addr-phone">{{order.receiverPhone}}</div><div class="tpl-addr-text">{{order.receiverAddress}}</div></div><h3 class="tpl-section-title">商品清单（核对无误后打勾）</h3><div class="items">{{items}}</div><div class="tpl-footer"><div class="tpl-sign-row"><span>打包员</span><span class="line"></span></div><div class="tpl-sign-row"><span>复核</span><span class="line"></span></div></div></div><style>.tpl-pack{font-family:"Helvetica Neue","Microsoft YaHei",sans-serif;color:#000;font-size:11px;line-height:1.4}.tpl-pack .tpl-header{text-align:center;border-bottom:2px solid #000;padding-bottom:6px;margin-bottom:10px}.tpl-pack .tpl-title{font-size:18px;font-weight:700;letter-spacing:2px}.tpl-pack .tpl-subtitle{font-size:9px;color:#666;letter-spacing:1px;margin-top:2px}.tpl-pack .tpl-meta-row{display:flex;justify-content:space-between;font-size:11px;margin-bottom:10px}.tpl-pack .tpl-meta-row .lbl{display:inline-block;width:42px;color:#666;font-size:10px}.tpl-pack .tpl-addr-block{border:1px solid #000;padding:8px 10px;margin-bottom:8px}.tpl-pack .tpl-addr-label{font-size:9px;color:#666;letter-spacing:2px;margin-bottom:3px}.tpl-pack .tpl-addr-name{font-size:15px;font-weight:700}.tpl-pack .tpl-addr-phone{font-size:11px;font-family:"Courier New",monospace;margin-top:1px}.tpl-pack .tpl-addr-text{font-size:11px;margin-top:3px;line-height:1.4}.tpl-pack .tpl-section-title{font-size:12px;font-weight:700;margin:8px 0 4px}.tpl-pack table{width:100%;border-collapse:collapse}.tpl-pack table th{background:#000;color:#fff;font-size:10px;text-align:left;padding:4px 6px}.tpl-pack table td{border-bottom:1px solid #999;padding:5px 6px;font-size:11px}.tpl-pack .tpl-footer{margin-top:12px;border-top:1px dashed #999;padding-top:8px}.tpl-pack .tpl-sign-row{display:flex;align-items:center;gap:8px;font-size:11px;margin-top:6px}.tpl-pack .tpl-sign-row .lbl{width:42px}.tpl-pack .tpl-sign-row .line{flex:1;border-bottom:1px solid #000;height:14px}</style>' WHERE `code` = 'PACK';

UPDATE `mo_print_template` SET `content_template` = '<div class="moyu-tpl tpl-ship"><div class="tpl-header"><div class="tpl-brand-block"><div class="tpl-brand-name">MOYUYO</div><div class="tpl-brand-tag">海外仓直发 · 全球速运</div></div><div class="tpl-doc-title"><div class="tpl-title">发货单</div><div class="tpl-subtitle">SHIPPING ORDER</div></div></div><div class="tpl-status-bar"><span>订单状态：<strong>{{order.statusLabel}}</strong></span><span>实付金额：<strong>{{order.payAmount}}</strong></span></div><div class="tpl-address-row"><div class="tpl-addr-block from"><div class="tpl-addr-label">FROM · 发件人</div><div class="tpl-addr-name">MOYUYO 海外仓</div><div class="tpl-addr-text">中国 · 跨境物流集散中心</div><div class="tpl-addr-text" style="margin-top:3px;">客服：support@moyuyo.com</div></div><div class="tpl-addr-arrow">▶</div><div class="tpl-addr-block to"><div class="tpl-addr-label">TO · 收件人</div><div class="tpl-addr-name">{{order.receiverName}}</div><div class="tpl-addr-phone">{{order.receiverPhone}}</div><div class="tpl-addr-text">{{order.receiverAddress}}</div></div></div><h3 class="tpl-section-title">商品明细</h3><div class="items">{{items}}</div><div class="tpl-footer"><div class="tpl-sign">发货人：__________</div><div class="tpl-sign">承运签字：__________</div><div class="tpl-sign">客户签收：__________</div></div><div class="tpl-bottom-line">{{template.name}} · {{paper}} · 打印：{{time}}</div></div><style>.tpl-ship{font-family:"Helvetica Neue","Microsoft YaHei",sans-serif;color:#000;font-size:11px;line-height:1.4}.tpl-ship .tpl-header{display:flex;justify-content:space-between;align-items:center;border-bottom:3px double #000;padding-bottom:8px;margin-bottom:10px}.tpl-ship .tpl-brand-name{font-size:20px;font-weight:900;letter-spacing:3px}.tpl-ship .tpl-brand-tag{font-size:9px;color:#666;letter-spacing:1px;margin-top:2px}.tpl-ship .tpl-doc-title{text-align:right}.tpl-ship .tpl-title{font-size:24px;font-weight:900;letter-spacing:4px}.tpl-ship .tpl-subtitle{font-size:9px;color:#666;letter-spacing:2px;margin-top:2px}.tpl-ship .tpl-status-bar{display:flex;gap:24px;background:#fff7ed;border:1px solid #fed7aa;padding:6px 12px;margin-bottom:10px;font-size:11px;border-radius:2px}.tpl-ship .tpl-status-bar strong{color:#c2410c;font-size:13px}.tpl-ship .tpl-address-row{display:flex;align-items:stretch;gap:8px;margin-bottom:10px}.tpl-ship .tpl-addr-block{flex:1;border:1px solid #000;padding:8px 10px}.tpl-ship .tpl-addr-block.from{background:#f7f7f7}.tpl-ship .tpl-addr-block.to{background:#fff;border-width:2px}.tpl-ship .tpl-addr-arrow{display:flex;align-items:center;font-size:18px;color:#999;font-weight:700}.tpl-ship .tpl-addr-label{font-size:9px;color:#666;letter-spacing:2px;margin-bottom:3px;border-bottom:1px solid #ddd;padding-bottom:2px}.tpl-ship .tpl-addr-name{font-size:15px;font-weight:700;margin-top:2px}.tpl-ship .tpl-addr-phone{font-size:11px;font-family:"Courier New",monospace;margin-top:1px}.tpl-ship .tpl-addr-text{font-size:11px;line-height:1.4}.tpl-ship .tpl-section-title{font-size:13px;font-weight:700;margin:10px 0 6px;padding:3px 8px;background:#000;color:#fff;letter-spacing:1px}.tpl-ship table{width:100%;border-collapse:collapse}.tpl-ship table th{background:#f0f0f0;border:1px solid #999;padding:5px 8px;text-align:left;font-size:10px;font-weight:700}.tpl-ship table td{border:1px solid #999;padding:6px 8px;font-size:11px}.tpl-ship .tpl-footer{display:flex;justify-content:space-between;margin-top:14px;padding-top:8px;border-top:1px dashed #999;font-size:11px;color:#444}.tpl-ship .tpl-sign{flex:1}.tpl-ship .tpl-bottom-line{margin-top:6px;text-align:center;font-size:9px;color:#888;letter-spacing:1px}</style>' WHERE `code` = 'SHIP';

UPDATE `mo_print_template` SET `content_template` = '<div class="moyu-tpl tpl-label"><div class="tpl-brand-row"><div class="tpl-brand-name">MOYUYO</div><div class="tpl-brand-tag">SHIPMENT LABEL</div></div><div class="tpl-to-block"><div class="tpl-to-label">SHIP TO</div><div class="tpl-to-name">{{order.receiverName}}</div><div class="tpl-to-phone">{{order.receiverPhone}}</div></div><div class="tpl-addr-block"><div class="tpl-addr-text">{{order.receiverAddress}}</div></div><div class="tpl-barcode"><div class="tpl-barcode-label">ORDER NO.</div><div class="tpl-barcode-no">{{order.orderNo}}</div><div class="tpl-barcode-stripes">||||||||||||||||||||||||||||||||||||</div></div><div class="tpl-from-row"><div class="tpl-from-label">FROM</div><div class="tpl-from-name">MOYUYO 海外仓</div></div><div class="tpl-bottom">{{time}}</div></div><style>.tpl-label{font-family:"Helvetica Neue","Microsoft YaHei",sans-serif;color:#000;font-size:11px;line-height:1.3;padding:4mm}.tpl-label .tpl-brand-row{display:flex;justify-content:space-between;align-items:center;border-bottom:1.5px solid #000;padding-bottom:3px;margin-bottom:6px}.tpl-label .tpl-brand-name{font-size:13px;font-weight:900;letter-spacing:2px}.tpl-label .tpl-brand-tag{font-size:8px;color:#666;letter-spacing:1px;font-weight:700}.tpl-label .tpl-to-block{margin-bottom:6px}.tpl-label .tpl-to-label{font-size:9px;color:#666;letter-spacing:2px;font-weight:700;margin-bottom:2px}.tpl-label .tpl-to-name{font-size:24px;font-weight:900;line-height:1.1;letter-spacing:1px}.tpl-label .tpl-to-phone{font-size:13px;font-family:"Courier New",monospace;font-weight:700;margin-top:2px}.tpl-label .tpl-addr-block{border:1.5px solid #000;padding:5px 6px;margin-bottom:8px;min-height:18mm}.tpl-label .tpl-addr-text{font-size:13px;font-weight:600;line-height:1.35}.tpl-label .tpl-barcode{text-align:center;border:1px solid #000;padding:4px;margin-bottom:6px;background:#fff}.tpl-label .tpl-barcode-label{font-size:8px;letter-spacing:2px;color:#666}.tpl-label .tpl-barcode-no{font-family:"Courier New",monospace;font-size:14px;font-weight:700;letter-spacing:1px;margin:1px 0}.tpl-label .tpl-barcode-stripes{font-family:monospace;font-size:14px;letter-spacing:0;color:#000;line-height:1;overflow:hidden}.tpl-label .tpl-from-row{border-top:1px dashed #666;padding-top:3px;display:flex;align-items:center;gap:6px}.tpl-label .tpl-from-label{font-size:8px;color:#666;letter-spacing:1px;font-weight:700}.tpl-label .tpl-from-name{font-size:10px;font-weight:600}.tpl-label .tpl-bottom{text-align:right;font-size:8px;color:#666;font-family:"Courier New",monospace;margin-top:2px}</style>' WHERE `code` = 'LABEL';